import commonjs from '@rollup/plugin-commonjs';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import typescript from '@rollup/plugin-typescript';

/**
 * Where the compiled scripts are written: the addon's maps/scripts folder, which is where a
 * point_script's cs_script keyvalue (maps/scripts/<name>.vjs) points. A running map hot-reloads a
 * script whose .js changes here. Do not edit the .js files: edit src/<name>/*.ts.
 */
const OUTPUT_DIR = '__OUTPUT_DIR__';

// The cs_script tool edits the lines between the two markers (one entry per script): keep the shape.
// cs-script:targets:begin
const targets = [
__TARGETS__
];
// cs-script:targets:end

// CS_SCRIPT_ONLY=<name> builds just that script.
const only = process.env.CS_SCRIPT_ONLY;

export default targets
  .filter(({ name }) => !only || name === only)
  .map(({ name, input, output, tsconfig }) => ({
    input,
    output: {
      file: output,
      format: 'esm',
      banner: `// GENERATED by cs_script (rollup) from cs_script/src/${name}: edit the .ts files, not this one`,
    },
    external: ['cs_script/point_script'],
    plugins: [
      typescript({ tsconfig, outDir: OUTPUT_DIR, noEmitOnError: true }),
      nodeResolve(),
      commonjs(),
    ],
  }));
